#!/usr/bin/env bash
# Cut a release: version from commits (or given), Cargo version + lock, CHANGELOG.md regenerated by
# git-cliff, one `chore(release): vX.Y.Z` commit, annotated tag `vX.Y.Z`. Local only, nothing pushed.
#   scripts/release.sh            next version from Conventional Commits (git-cliff --bumped-version)
#   scripts/release.sh 1.2.0      explicit version
#   scripts/release.sh --dry-run  print the version and the changelog section, change nothing
set -euo pipefail

cd "$(dirname "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")")"

die() {
  echo "release.sh: $*" >&2
  exit 1
}

dry=0
version=""
for arg in "$@"; do
  case $arg in
    --dry-run) dry=1 ;;
    -h | --help) sed -n '2,6p' "$0"; exit 0 ;;
    [0-9]*) version=$arg ;;
    *) die "unknown argument '$arg'" ;;
  esac
done

for tool in git-cliff cargo; do
  command -v "$tool" > /dev/null || die "$tool not on PATH (run inside devenv shell)"
done

[[ $(git branch --show-current) == main ]] || die "release from main"
[[ -z $(git status --porcelain --untracked-files=no) ]] || die "working tree has uncommitted changes"

# git-cliff logs INFO/WARN to stderr in color; keep stderr only to report the ERROR line on failure.
export NO_COLOR=1
err=$(mktemp)
trap 'rm -f "$err"' EXIT
cliff_error() { grep -m1 'ERROR' "$err" || tail -1 "$err"; }

if [[ -z $version ]]; then
  version=$(git cliff --bumped-version 2> "$err") || die "git cliff --bumped-version failed: $(cliff_error)"
  version=${version#v}
fi
[[ $version =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || die "bad version '$version' (expected X.Y.Z)"
tag=v$version
! git rev-parse -q --verify "refs/tags/$tag" > /dev/null || die "tag $tag already exists"
notes=$(git cliff --unreleased --tag "$tag" --strip header 2> "$err") || die "git cliff failed: $(cliff_error)"
[[ $notes == *$'\n- '* ]] ||
  die "no feat/fix/perf/refactor/docs commits since the last tag: nothing to release"

if ((dry)); then
  echo "would release $tag"
  printf '%s\n' "$notes"
  exit 0
fi

scripts/check.sh

current=$(cargo metadata --no-deps --format-version 1 | grep -o '"version":"[^"]*"' | head -1 | cut -d'"' -f4)
if [[ $current != "$version" ]]; then
  cargo set-version --workspace "$version"
  cargo update --workspace --offline -q
fi
git cliff --tag "$tag" -o CHANGELOG.md 2> "$err" || die "git cliff could not write CHANGELOG.md: $(cliff_error)"

git add Cargo.toml Cargo.lock CHANGELOG.md
git ls-files -z -- '*/Cargo.toml' | xargs -0 -r git add --
git commit -m "chore(release): $tag"
git tag -a "$tag" -m "$tag"
echo "released $tag (local commit and tag; nothing pushed)"
